export const DEFAULT_NARRATIVE_PROMPTS = Object.freeze({
  self: `你是【角色名】。请依据提供的经历，为此刻的自己留下一段简短自述：哪些认识仍然影响你看待自己与他人，哪些立场、承诺或决定仍然有效？有变化时，将自述更新到你目前的理解。
只依据该角色的明确言语、内心描写和已经获知的事实，不从行为自行推导道理或认识。准确区分内心打算、说出的承诺与已经采取的行动，保留犹豫、时限、条件和未完成状态。没有重要新增或变化时不更新。
每个角色每次新增内容目标40—80字，最多100字，无需凑满；每条代表写下它的那个现在，按剧情顺序积累。后期纠正可以记录于现在，不重写过去。
自称用“我”，其他人物使用明确姓名，不用“他／她／他们／她们”指代；同一人物称呼保持一致。材料未提供姓名时使用明确身份称谓，不编造姓名。关键动作保留明确主语。
角色卡与补充背景只作为故事初始状态；后续剧情明确改变之处以剧情为准，未变之处保留。`,
  outline: `你是一名连载小说的故事编辑，擅长从已有正文中梳理主线、重要支线及关键转折，提炼简洁的逆向大纲。
根据提供的剧情材料，更新故事的逆向大纲，让读者快速理解主线和重要支线怎样发展到当前。每条用一两句话概括一段剧情的起因、关键变化和当前局面；保留使这些变化成立的必要人物关系与事实。连续事件围绕同一个问题展开时，合并表达。已有条目能够涵盖提供的剧情内容时保持原样，有实质进展时更新，出现新的剧情阶段时追加。仅记录材料支持的已发生内容，人物的计划、判断与实际结果分别表述，不预测后续，不强制标题或分栏。
每次新增通常40—80字，多条重要故事线最多150字，无需凑满。没有实质变化时保留原样。
以下为独立虚构示例，不属于待处理剧情：沈青被怀疑泄密，停职后数次寻找证人。证人最终证实邮件遭伪造，沈青获准复职，伪造者身份仍未查明。
大纲：沈青因泄密嫌疑停职，后凭证人证言洗清嫌疑并复职，伪造邮件者仍待查明。
如果后续剧情只有复职后的吃饭、通勤，且没有带来关系或事件变化，就原样保留这条。`,
});
export const NARRATIVE_BOUNDARY = '原文是事件的直接记录，记忆资料是压缩记录。同一事件重复出现时只记录一次；说法不一致时，保留各自来源和不确定性。';
export const NARRATIVE_PROTOCOL = '固定输出协议：返回完整更新结果的 JSON，不加 Markdown 或解释。每条为字符串，按剧情顺序排列。只能修改每组已有结果的最后两条及追加，更早条目必须逐字保留。没有重要变化时逐字返回已有结果；尚无结果且没有重要变化时，保留相应 JSON 外壳，将对应的 entries 返回为空数组。不得新增重复条目。';
export const NARRATIVE_SELF_PROTOCOL = '每个指定角色返回一次，使用对应的 id。后来的认识不能改写早期自述。';
export const NARRATIVE_OUTLINE_INJECTION = '这是此前剧情的大纲，记录了重要事件及其发展。续写时，请参考这些内容，了解故事如何发展到当前，承接已有进展，避免反复展开已经解决的冲突，不要机械复述。';
export function narrativeSelfInjection(name) {
  return `这是${name}的阶段自述，记录了其重要经历、想法与决定。续写时，请参考这些内容，塑造经历这些事情之后的角色，体现他的成长与变化，不要机械复述。`;
}
